try:
    parser = createparser()
    args = parser.parse_args(args=cliargs)

    # If no subcommand was provided (args has no 'which' attribute),
    # argparse will have already printed an error and exited.
    # But we need to handle the case where no args were given at all.
    if not hasattr(args, 'which'):
        parser.print_help()
        return 2

    # Dispatch based on which attribute
    if args.which == "bump":
        result = cmd_bump(args)
    elif args.which == "compare":
        result = cmd_compare(args)
    elif args.which == "check":
        result = cmd_check(args)
    else:
        result = process(args)

    print(result)
    return 0

except SystemExit:
    raise
except (ValueError, TypeError) as err:
    print("ERROR", err, file=sys.stderr)
    return 2
